"use client";
import {useActionState} from "react";
import {ShieldCheck,Send} from "lucide-react";
import {configureConcerns,respondConcern,sendConcern,type ConcernState} from "@/app/app/concerns/actions";
function Result({state}:{state:ConcernState}){return <>{state.error&&<p role="alert" className="form-message">{state.error}</p>}{state.success&&<p role="status" className="form-message success">{state.success}</p>}</>;}
export function ConcernForm({id,alternate}:{id:string;alternate:boolean}){
 const[state,action,pending]=useActionState(sendConcern,{});
 return <form action={action} className="stack-form"><input type="hidden" name="id" value={id}/><label>Reporting route<select name="route"><option value="primary">Designated reporting team</option>{alternate&&<option value="alternate">Alternative route: conflict with the primary team</option>}</select></label><label>Subject<input name="title" required minLength={5} maxLength={200}/></label><label>Your concern<textarea name="body" required minLength={10} maxLength={10000} rows={7}/></label><label className="policy-choice"><input type="checkbox" name="acknowledged" required/><span>I understand this is a confidential, named report. My account identity is available to the designated handlers. This is not anonymous.</span></label><Result state={state}/><button className="button button-primary" disabled={pending||Boolean(state.success)}><Send size={16}/>{pending?"Submitting...":"Submit confidential report"}</button></form>;
}
export function ConcernResponse({id}:{id:string}){const[state,action,pending]=useActionState(respondConcern,{});return <form action={action} className="stack-form"><input type="hidden" name="id" value={id}/><label>Status<select name="status"><option value="acknowledged">Acknowledged</option><option value="reviewing">Under review</option><option value="closed">Close with response</option></select></label><label>Response to the reporting person<textarea name="reply" required minLength={5} maxLength={5000} rows={4}/></label><Result state={state}/><button className="button button-primary" disabled={pending}>Save response</button></form>;}
export function ConcernConfiguration({members,route}:{members:Array<{id:string;name:string}>;route:{primary_handlers:string[];alternate_handlers:string[];guidance:string}|null}){
 const[state,action,pending]=useActionState(configureConcerns,{});
 return <form action={action} className="stack-form"><h2>Confidential reporting routes</h2><div className="company-field-grid">{(["primary","alternate"] as const).map(kind=><fieldset key={kind}><legend>{kind==="primary"?"Primary handlers":"Independent alternate handlers"}</legend>{members.map(m=><label className="policy-choice" key={m.id}><input type="checkbox" name={kind} value={m.id} defaultChecked={route?.[`${kind}_handlers`].includes(m.id)}/><span>{m.name}</span></label>)}</fieldset>)}</div><label>Company reporting guidance<textarea name="guidance" maxLength={3000} rows={4} defaultValue={route?.guidance||""}/></label><Result state={state}/><button className="button button-primary" disabled={pending}><ShieldCheck size={16}/>Save reporting routes</button></form>;
}
